    private static readonly FrozenDictionary<string, MobSpawnDefinition[]> RenewalByMap = RathenaRenewalDefault
        .GroupBy(spawn => spawn.Map, StringComparer.OrdinalIgnoreCase)
        .ToFrozenDictionary(group => group.Key, group => group.ToArray(), StringComparer.OrdinalIgnoreCase);
    private static readonly FrozenDictionary<string, MobSpawnDefinition[]> EffectiveByMap = AthenaIroEffective
        .GroupBy(spawn => spawn.Map, StringComparer.OrdinalIgnoreCase)
        .ToFrozenDictionary(group => group.Key, group => group.ToArray(), StringComparer.OrdinalIgnoreCase);

    internal static IReadOnlyList<MobSpawnDefinition> GetForMap(string map, MobSpawnLoadProfile profile) => profile switch
    {
        MobSpawnLoadProfile.RathenaRenewalDefault => RenewalByMap.TryGetValue(map, out var renewal) ? renewal : [],
        MobSpawnLoadProfile.AthenaIroEffective => EffectiveByMap.TryGetValue(map, out var effective) ? effective : [],
        _ => throw new ArgumentOutOfRangeException(nameof(profile)),
    };
